func (q *Queries) UpsertSyncSubscription(ctx context.Context, arg UpsertSyncSubscriptionParams) (AppSyncSubscription, error) {
	row := q.db.QueryRow(ctx, upsertSyncSubscription,
		arg.EntityKind,
		arg.EntityID,
		arg.RouteID,
		arg.ActingCharacterID,
	)
	var i AppSyncSubscription
	err := row.Scan(
		&i.SubscriptionID,
		&i.EntityKind,
		&i.EntityID,
		&i.RouteID,
		&i.Enabled,
		&i.ActingCharacterID,
		&i.NextDueAt,
		&i.LastSuccessAt,
		&i.LastStatus,
		&i.Etag,
		&i.LastModified,
		&i.CursorAfter,
		&i.Consecutive304,
		&i.Consecutive403,
		&i.SnoozedUntil,
		&i.OptInNoCache,
	)
	return i, err
}
